def solve(board):
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                for d in range(1, 10):
                    if ok(board, r, c, d):
                        board[r][c] = d
                        if solve(board):
                            return True
                        board[r][c] = 0            # undo and try the next digit
                return False                       # no digit fits: backtrack
    return True

def ok(board, r, c, d):
    if any(board[r][i] == d or board[i][c] == d for i in range(9)):
        return False
    br, bc = 3 * (r // 3), 3 * (c // 3)
    return all(board[br + i][bc + j] != d for i in range(3) for j in range(3))

