def minimax(pile, my_turn):
    if pile == 0:
        return -1 if my_turn else 1        # the previous player took the last item and won
    scores = [minimax(pile - take, not my_turn) for take in (1, 2, 3) if take <= pile]
    return max(scores) if my_turn else min(scores)

def best_move(pile):
    return max((t for t in (1, 2, 3) if t <= pile), key=lambda t: minimax(pile - t, False))

print([minimax(n, True) for n in range(1, 9)])   # [1, 1, 1, -1, 1, 1, 1, -1]
print(best_move(6))                              # 2, leaving the opponent a multiple of 4

import random

def estimate_pi(samples):
    inside = sum(random.random() ** 2 + random.random() ** 2 <= 1 for _ in range(samples))
    return 4 * inside / samples

for n in (1_000, 100_000, 1_000_000):
    print(n, round(estimate_pi(n), 4))     # approaches 3.1416, slowly (error ~ 1/sqrt(n))

import random

def quickselect(a, k):
    pivot = random.choice(a)
    smaller = [x for x in a if x < pivot]
    equal = [x for x in a if x == pivot]
    if k < len(smaller):
        return quickselect(smaller, k)
    if k < len(smaller) + len(equal):
        return pivot
    return quickselect([x for x in a if x > pivot], k - len(smaller) - len(equal))

data = [random.randrange(10**6) for _ in range(10_001)]
print(quickselect(data, 5000) == sorted(data)[5000])   # True, every time

import random

random.seed(7)
TARGET = "hello world"
LETTERS = "abcdefghijklmnopqrstuvwxyz "

def fitness(s):
    return sum(a == b for a, b in zip(s, TARGET))

def mutate(s):
    i = random.randrange(len(s))
    return s[:i] + random.choice(LETTERS) + s[i + 1:]

def crossover(a, b):
    cut = random.randrange(len(a))
    return a[:cut] + b[cut:]

pop = ["".join(random.choice(LETTERS) for _ in TARGET) for _ in range(100)]
for gen in range(500):
    pop.sort(key=fitness, reverse=True)
    if pop[0] == TARGET:
        break
    parents = pop[:20]
    pop = parents + [mutate(crossover(random.choice(parents), random.choice(parents))) for _ in range(80)]
print(gen, pop[0])      # the generation count and the evolved phrase

def run(rules, tape, state="start", steps=1000):
    tape, head = dict(enumerate(tape)), 0
    for _ in range(steps):
        if state == "halt":
            break
        symbol = tape.get(head, "_")
        write, move, state = rules[(state, symbol)]
        tape[head] = write
        head += 1 if move == "R" else -1
    return "".join(tape[i] for i in sorted(tape)).strip("_")

rules = {
    ("start", "0"): ("0", "R", "start"), ("start", "1"): ("1", "R", "start"),
    ("start", "_"): ("_", "L", "carry"),
    ("carry", "1"): ("0", "L", "carry"), ("carry", "0"): ("1", "L", "halt"),
    ("carry", "_"): ("1", "L", "halt"),
}
print(run(rules, "1011"))    # 1100, since 11 + 1 = 12

transitions = {
    ("locked", "coin"): "unlocked",
    ("locked", "push"): "locked",
    ("unlocked", "coin"): "unlocked",
    ("unlocked", "push"): "locked",
}

def run(events, state="locked"):
    for event in events:
        state = transitions[(state, event)]
    return state

print(run(["push", "coin", "push"]))       # locked
print(run(["coin", "coin"]))               # unlocked
